'use strict';
const EXCLUSION_CATEGORIES={jump:{label:'Jumping exercises',test:m=>/\bjump/i.test(m.name)},overhead:{label:'Overhead presses',test:m=>m.pattern==='overhead press'},lunge:{label:'Lunges and split squats',test:m=>['lunge','split squat'].includes(m.pattern)}};
const exclusionQueries={settings:'',setup:''};
function isMovementExcluded(m,bans=[]){const id=m.id||Object.values(MOVES).find(x=>x.name===m.name)?.id;return bans.some(value=>{if(value.startsWith('move:'))return id===value.slice(5);if(value.startsWith('group:'))return m.group===value.slice(6);if(value.startsWith('category:'))return EXCLUSION_CATEGORIES[value.slice(9)]?.test(m)||false;return norm(m.name+' '+(MUSCLE_GROUPS[m.group]||'')+' '+(m.pattern||'')).includes(norm(canonicalExclusion(value)).replace(/^no /,''));});}
function exclusionLabel(value){if(value.startsWith('move:'))return MOVES[value.slice(5)]?.name||value.slice(5);if(value.startsWith('group:'))return MUSCLE_GROUPS[value.slice(6)]||value.slice(6);if(value.startsWith('category:'))return EXCLUSION_CATEGORIES[value.slice(9)]?.label||value.slice(9);return value;}
function exclusionPanel(context){const p=context==='setup'?setupDraft:profile(),disabled=hasActive(),bans=p.bans||[];return `<div class="exclusion-panel" data-exclusion-context="${context}"><p class="small muted">Choose exercises or movement types to skip. Your choices apply to upcoming workouts.</p><div class="chips">${Object.entries(EXCLUSION_CATEGORIES).map(([id,c])=>{const value='category:'+id;return `<button type="button" class="chip ${bans.includes(value)?'selected':''}" data-exclusion="${esc(value)}" data-context="${context}" aria-pressed="${bans.includes(value)}" ${disabled?'disabled':''}>${bans.includes(value)?'✓ ': '+ '}${c.label}</button>`;}).join('')}</div><label for="exclude-search-${context}">Find an exercise to exclude</label><input type="search" id="exclude-search-${context}" data-exclusion-search="${context}" value="${esc(exclusionQueries[context])}" placeholder="Search by exercise name" autocomplete="off" ${disabled?'disabled':''}><div class="exclusion-results" data-exclusion-results="${context}" aria-live="polite">${exclusionResults(context,exclusionQueries[context])}</div><div class="excluded-selection"><h3>Currently excluded</h3>${bans.length?`<div class="chips">${bans.map(value=>`<button type="button" class="chip selected" data-exclusion="${esc(value)}" data-context="${context}" ${disabled?'disabled':''}><span>${esc(exclusionLabel(value))}</span> ×</button>`).join('')}</div>`:'<p class="small muted">No exercises excluded.</p>'}</div><details><summary>Exclude a muscle group</summary><div class="chips">${Object.entries(MUSCLE_GROUPS).map(([id,label])=>{const value='group:'+id;return `<button type="button" class="chip ${bans.includes(value)?'selected':''}" data-exclusion="${value}" data-context="${context}" aria-pressed="${bans.includes(value)}" ${disabled?'disabled':''}>${label}</button>`;}).join('')}</div></details></div>`;}
function exclusionResults(context,query){if(!query.trim())return '';const p=context==='setup'?setupDraft:profile(),terms=norm(query).split(' ').filter(Boolean),matches=Object.values(MOVES).filter(m=>!m.retired&&!m.libraryAlias&&terms.every(term=>norm(m.name+' '+translateText(m.name)+' '+(m.searchAliases||'')).includes(term)));if(!matches.length)return '<p class="small muted">No matching exercises.</p>';return matches.slice(0,12).map(m=>{const selected=p.bans.includes('move:'+m.id);return `<button type="button" class="exclusion-result" data-exclusion="move:${m.id}" data-context="${context}" aria-pressed="${selected}" ${hasActive()?'disabled':''}><span><strong>${esc(m.name)}</strong><small>${esc(MUSCLE_GROUPS[m.group])}</small></span><span>${selected?'✓':'+'}</span></button>`;}).join('')+(matches.length>12?'<p class="small muted">Keep typing to narrow the list.</p>':'');}
function toggleExclusion(context,value){if(hasActive())return;const p=context==='setup'?setupDraft:profile();if(!p)return;if(!(value.startsWith('move:')||value.startsWith('group:')||value.startsWith('category:')||p.bans.includes(value)))return;p.bans=p.bans.includes(value)?p.bans.filter(x=>x!==value):[...p.bans,value];if(context==='settings'){p.workoutOverrides=null;previewSwaps={};persist();}render();}
document.addEventListener('input',e=>{const context=e.target.dataset.exclusionSearch;if(!context)return;exclusionQueries[context]=e.target.value;document.querySelector(`[data-exclusion-results="${context}"]`).innerHTML=exclusionResults(context,e.target.value);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-exclusion]');if(b&&!b.disabled)toggleExclusion(b.dataset.context,b.dataset.exclusion);});
function landmineHelp(){return '<details class="equipment-help"><summary>What is a landmine adapter?</summary><p class="small muted">A landmine adapter is a pivoting holder that fixes one end of a barbell to the floor or rack. The free end moves in an arc for presses and rows. Only select it if you have a purpose-built attachment.</p></details>';}
